def run_stateful_simulation(
    symbols:        list[str],
    prices_map:     dict[str, list[float]],
    dates_map:      dict[str, list[str]],
    spx_prices:     list[float],
    spx_dates:      list[str],
    ohlc_map:       dict = None,
    assumptions:    dict = None,
    step:           int  = 1,
    min_history:    int  = 120,
    market_score_default: float = 60.0,
    sim_start_date: str  = None,  # 交易执行起始日（None=从 min_history 后开始）
    sim_end_date:   str  = None,  # 交易执行截止日（None=到末尾）
    ndx_prices:     list = None,  # NDX 收盘价（Gate v2 Leadership 判断）
    ndx_dates:      list = None,
    sox_prices:     list = None,  # SOX 收盘价
    sox_dates:      list = None,
    vix_prices:     list = None,  # VIX 收盘价
    vix_dates:      list = None,
) -> dict:
    """
    Layer D v1.6: Strict Top3 + RS threshold + MinHold + Relative SPX Stop

    修正项（相比 v3）：
    1. SPX master calendar — 时间轴以 SPX dates 为准
    2. Date-based alignment — 所有股票按日期查找，不用 index 直接对齐
    3. skipped_orders_by_reason — 跳过原因分类统计
    4. sample_validity 检查 — 样本不足时返回 INSUFFICIENT_SAMPLE
    """
    logger.info("[Backtest Layer D v1.6] Strict Top3 + RS/MinHold/RelStop Backtest...")

    # ── 冻结参数 ─────────────────────────────────────────
    a        = assumptions or LAYER_D_ASSUMPTIONS
    max_pos  = a["max_positions"]
    buy_pct  = a["buy_size"]  / max_pos       # Top3: 1/3 per full slot
    add_pct  = a["add_size"]  / max_pos       # Top3: +1/6, only useful after REDUCE
    max_pct  = a["max_single_size"] / max_pos # Top3: max 1/3 per position
    one_way  = a["total_one_way"]             # 0.001
    init_cap = float(a.get("initial_capital", 100_000))
    strategy_variant = a.get("strategy_variant", "top3_entry_rs_minhold_relstop")
    e1r_shell_mode = bool(a.get("e1r_shell_mode", False))
    e1r_regime_wiring_enabled = bool(a.get("e1r_regime_wiring_enabled", False))
    e1r_uptrend_execution_enabled = bool(a.get("e1r_uptrend_execution_enabled", False))
    e1r_regime_daily = a.get("e1r_regime_daily", {}) or {}

    def _e1r_regime_on(date: str) -> str:
        if not e1r_regime_wiring_enabled or not date:
            return "N/A"
        rec = e1r_regime_daily.get(date, {})
        if isinstance(rec, dict):
            return rec.get("regime") or rec.get("spx_regime") or rec.get("weekly_regime") or "UNCLASSIFIED"
        if isinstance(rec, str):
            return rec
        return "UNCLASSIFIED"

    def _e1r_mode_for_regime(regime: str) -> str:
        if regime == "UPTREND":
            return "UPTREND_EMERGING_CONFIRMED_ENABLED"
        if regime == "SIDEWAYS":
            return "SIDEWAYS_QUALITY_BREAKOUT_ONLY"
        if regime == "DOWNTREND":
            return "DOWNTREND_EXCEPTION_ONLY"
        if regime == "N/A":
            return "N/A"
        return "UNCLASSIFIED_NO_RISK_EXPANSION"

    def _e1r_risk_budget_for_regime(regime: str) -> dict:
        if regime == "UPTREND":
            return {"mode": "UPTREND_RISK_ON", "max_positions": 3, "max_total_exposure_pct": 100.0}
        if regime == "SIDEWAYS":
            return {"mode": "SIDEWAYS_LIMITED", "max_positions": 2, "max_total_exposure_pct": 33.3}
        if regime == "DOWNTREND":
            return {"mode": "DOWNTREND_DEFENSIVE", "max_positions": 1, "max_total_exposure_pct": 10.0}
        if regime == "N/A":
            return {"mode": "N/A", "max_positions": None, "max_total_exposure_pct": None}
        return {"mode": "UNCLASSIFIED_DEFENSIVE", "max_positions": 0, "max_total_exposure_pct": 0.0}

    def _e1r_dominant_regime(weights: dict) -> str:
        if not weights:
            return "UNCLASSIFIED" if e1r_regime_wiring_enabled else "N/A"

def rank_entrypoint_candidates(scans: dict[str, Any]) -> list[dict[str, Any]]:
    candidates = []

    for path, scan in scans.items():
        for f in scan.get("function_defs", []):
            name = f["name"]
            lower = name.lower()
            score = f.get("score", 0)

            if "stateful" in lower:
                score += 80
            if "simulation" in lower:
                score += 60
            if "portfolio" in lower:
                score += 50
            if "backtest" in lower:
                score += 40
            if "variant" in lower:
                score += 30
            if name.startswith("run_"):
                score += 20

            body = f.get("body_head", "")
            if "daily_records" in body:
                score += 30
            if "total_equity" in body or "portfolio_value" in body:
                score += 30
            if "cash" in body:
                score += 20
            if "positions_value" in body or "market_value" in body:
                score += 20
            if "spx_regime" in body or "market_gate_state" in body:
                score += 20

            candidates.append({
                "source": path,
                "name": name,
                "line": f.get("line"),
                "end_line": f.get("end_line"),
                "args": f.get("args"),
                "score": score,
                "body_head": body,
            })

    return sorted(candidates, key=lambda x: (-x["score"], x["source"], x["line"]))[:40]

def normalize_backtest_e1(rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    out = []
    first = None
    for r in rows:
        d = get_date(r)
        e = as_float(r.get("equity") or r.get("portfolio_value") or r.get("total_equity"))
        if not d or e is None:
            continue
        if first is None:
            first = e
        out.append({
            "date": d,
            "strategy_id": "E1_AUDITED_G4_MINHOLD10",
            "curve_type": "backtest_5y",
            "canonical": True,
            "equity": e,
            "indexed": e / first * 100.0 if first else None,
        })
    return out

def validate_portfolio_candidate(stats: dict[str, Any]) -> dict[str, Any]:
    reasons = []

    checks = {
        "row_count_ge_1000": (stats.get("parseable_equity_rows") or 0) >= 1000,
        "one_row_per_date": stats.get("one_row_per_date") is True,
        "not_symbol_level": (stats.get("symbol_row_count") or 0) == 0,
        "not_diagnostic_only": (stats.get("diagnostic_only_row_count") or 0) == 0,
        "max_rows_per_date_eq_1": stats.get("max_rows_per_date") == 1,
        "total_return_close_to_frozen_1pct": (
            stats.get("total_return_abs_diff_vs_frozen") is not None
            and stats["total_return_abs_diff_vs_frozen"] <= 1.0
        ),
        "maxdd_close_to_frozen_1_5pct": (
            stats.get("maxdd_abs_diff_vs_frozen") is not None
            and stats["maxdd_abs_diff_vs_frozen"] <= 1.5
        ),
    }

    for k, ok in checks.items():
        if not ok:
            reasons.append(k)

    return {
        "checks": checks,
        "accepted_as_portfolio_daily_equity": all(checks.values()),
        "rejection_reasons": reasons,
    }

def load_existing_5y_generation_inputs() -> Dict[str, Any]:
    """
    Dry-run only.

    This function intentionally does not write canonical exports.
    It inspects whether the current repository has enough persisted inputs
    to generate E1R 5Y interval records:
      core_daily_equity_records + sidecar_records
      -> extract_core_interval_returns(...)
      -> build_equity_records_from_returns(...)
    """
    from src.engine import e1r_composer as composer  # type: ignore

    source_summary: Dict[str, Any] = {
        "core_sources": [],
        "sidecar_sources": [],
        "interval_sources": [],
    }

    def list_shape(label: str, rows: Any) -> Dict[str, Any]:
        if not isinstance(rows, list):
            return {"label": label, "is_list": False}
        keys = set()
        for row in rows[:50]:
            if isinstance(row, dict):
                keys.update(row.keys())
        return {
            "label": label,
            "is_list": True,
            "length": len(rows),
            "keys": sorted(keys),
            "has_core_minimum": (
                "date" in keys and (
                    "daily_return" in keys
                    or "daily_return_pct" in keys
                    or "total_equity" in keys
                    or "equity" in keys
                )
            ),
            "has_sidecar_minimum": (
                "date" in keys
                and "next_date" in keys
                and (
                    "sidecar_return" in keys
                    or "sidecar_return_pct" in keys
                )
            ),
            "has_interval_minimum": (
                "date" in keys
                and "next_date" in keys
                and "combined_return" in keys
            ),
        }

    def append_if_list(bucket: str, label: str, rows: Any) -> None:
        shape = list_shape(label, rows)
        if shape.get("is_list"):
            source_summary[bucket].append(shape)

    portfolio = read_json(ROOT / "exports/portfolio_backtest.json", default={})
    append_if_list("core_sources", "exports/portfolio_backtest.json.daily_records", portfolio.get("daily_records"))
    variant_results = portfolio.get("variant_results") if isinstance(portfolio, dict) else {}
    if isinstance(variant_results, dict):
        for variant, obj in variant_results.items():
            if isinstance(obj, dict):
                append_if_list("core_sources", f"exports/portfolio_backtest.json.variant_results.{variant}.daily_records", obj.get("daily_records"))

    oos_e1 = read_json(ROOT / "exports/oos_equity_curve.json", default={})
    if isinstance(oos_e1, dict):
        append_if_list("core_sources", "exports/oos_equity_curve.json.curve", oos_e1.get("curve"))

    e1r_diag = read_json(ROOT / "exports/e1r_v0_2_backtest_equity_curve.json", default={})
    if isinstance(e1r_diag, dict):
        append_if_list("core_sources", "exports/e1r_v0_2_backtest_equity_curve.json.rows", e1r_diag.get("rows"))
        append_if_list("core_sources", "exports/e1r_v0_2_backtest_equity_curve.json.equity_curve", e1r_diag.get("equity_curve"))

    sidecar = read_json(ROOT / "exports/oos_e1r_v0_2_sidecar.json", default={})
    if isinstance(sidecar, dict):
        for k, v in sidecar.items():
            append_if_list("sidecar_sources", f"exports/oos_e1r_v0_2_sidecar.json.{k}", v)

def try_import_backtest() -> dict[str, Any]:
    sys.path.insert(0, str(ROOT))
    sys.path.insert(0, str(ROOT / "src"))

    out = {
        "attempted": True,
        "ok": False,
        "error": None,
        "traceback_tail": None,
        "objects": {},
    }

    try:
        spec = importlib.util.spec_from_file_location("backtest_4c2a", BACKTEST)
        if spec is None or spec.loader is None:
            raise RuntimeError("cannot create import spec")
        mod = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = mod
        spec.loader.exec_module(mod)

        out["ok"] = True

        for name in dir(mod):
            if name.startswith("_"):
                continue
            lower = name.lower()
            if any(k in lower for k in ["backtest", "simulation", "portfolio", "variant", "stateful", "run"]):
                obj = getattr(mod, name)
                item = {"type": type(obj).__name__}
                if callable(obj):
                    try:
                        item["signature"] = str(inspect.signature(obj))
                    except Exception as exc:
                        item["signature_error"] = type(exc).__name__ + ": " + str(exc)
                out["objects"][name] = item

    except Exception as exc:
        out["error"] = type(exc).__name__ + ": " + str(exc)
        out["traceback_tail"] = traceback.format_exc()[-12000:]

    return out

def build_backtest_intervals(
    spx: dict[str, Any],
    regimes: dict[str, dict[str, Any]],
    config: E1RSidecarConfig,
) -> list[tuple[str, str]]:
    dates = [
        d for d in spx["dates"]
        if config.start_date <= d <= config.end_date
        and d in regimes
    ]
    dates = sorted(dates)
    return list(zip(dates[:-1], dates[1:]))

def extract_variant(variants: dict[str, Any], strategy_id: str) -> dict[str, Any]:
    if strategy_id not in variants:
        available = sorted(variants.keys())
        raise RuntimeError(
            f"Missing variant: {strategy_id}. "
            f"Available variants: {available}. "
            "Run full 5Y backtest with E1R v0.2 engine first."
        )
    return variants[strategy_id]

def summarize_combined_variant(
    interval_records: Sequence[dict[str, Any]],
    equity_records: Sequence[dict[str, Any]],
    initial_equity: float,
) -> dict[str, Any]:
    combined_returns = [safe_float(r.get("combined_return")) or 0.0 for r in interval_records]
    core_returns = [safe_float(r.get("core_return")) or 0.0 for r in interval_records]
    sidecar_returns = [safe_float(r.get("sidecar_return")) or 0.0 for r in interval_records]
    spx_returns = [safe_float(r.get("spx_return")) or 0.0 for r in interval_records]

    equity_curve = [initial_equity] + [
        safe_float(r.get("equity")) or initial_equity for r in equity_records
    ]

    total_return = compound_return(combined_returns)
    core_return = compound_return(core_returns)
    sidecar_return = compound_return(sidecar_returns)
    spx_return = compound_return(spx_returns)

    active_records = [r for r in interval_records if r.get("sidecar_active")]

    active_by_regime: dict[str, int] = {}
    active_by_subclass: dict[str, int] = {}
    contribution_by_regime: dict[str, float] = {}
    contribution_by_subclass: dict[str, float] = {}

    for row in interval_records:
        regime = row.get("regime") or "NO_REGIME"
        subclass = row.get("subclass") or "NO_SUBCLASS"
        sidecar_return_row = safe_float(row.get("sidecar_return")) or 0.0

        contribution_by_regime[regime] = contribution_by_regime.get(regime, 0.0) + sidecar_return_row
        contribution_by_subclass[subclass] = contribution_by_subclass.get(subclass, 0.0) + sidecar_return_row

        if row.get("sidecar_active"):
            active_by_regime[regime] = active_by_regime.get(regime, 0) + 1
            active_by_subclass[subclass] = active_by_subclass.get(subclass, 0) + 1

    return {
        "total_return_pct": pct_display(total_return),
        "core_return_pct": pct_display(core_return),
        "sidecar_return_pct": pct_display(sidecar_return),
        "spx_return_pct": pct_display(spx_return),
        "alpha_pct": pct_display(total_return - spx_return),
        # Match legacy engine convention:
        # max_drawdown_pct is reported as positive magnitude, e.g. 25.90 not -25.90.
        "max_drawdown_pct": abs(pct_display(max_drawdown(equity_curve)) or 0.0),
        "profit_factor": profit_factor(combined_returns),
        "sharpe_ratio": sharpe_ratio(combined_returns),
        "daily_win_rate_pct": (
            100.0 * sum(1 for r in combined_returns if r > 0) / len(combined_returns)
            if combined_returns else None
        ),
        "total_days": len(interval_records),
        "daily_equity_record_count": len(equity_records),
        "sidecar_active_days": len(active_records),
        "sidecar_active_by_regime": active_by_regime,
        "sidecar_active_by_subclass": active_by_subclass,
        "sidecar_simple_contribution_by_regime_pct": {
            k: pct_display(v)
            for k, v in contribution_by_regime.items()
        },
        "sidecar_simple_contribution_by_subclass_pct": {
            k: pct_display(v)
            for k, v in contribution_by_subclass.items()
        },
    }

def total_equity(self, prices: dict) -> float:
        hv = sum(
            h["units"] * prices.get(sym, h["entry_price"])
            for sym, h in self.holdings.items()
        )
        return self.cash + hv

def infer_contract(defs_by_file: dict[str, Any], grep_by_file: dict[str, Any], import_probe: dict[str, Any]) -> dict[str, Any]:
    findings = []
    risks = []
    next_actions = []

    generator_text = read_text(GENERATOR) if GENERATOR.exists() else ""
    composer_text = read_text(COMPOSER) if COMPOSER.exists() else ""

    has_compose_call_in_generator = "compose_e1r_v0_2_variant" in generator_text
    has_core_var_in_generator = "core_variant_result" in generator_text
    has_sidecar_var_in_generator = "sidecar_result" in generator_text
    has_daily_in_generator = ("daily_equity_records" in generator_text) or ("daily_records" in generator_text) or ("equity_curve" in generator_text)

    has_compose_def = "def compose_e1r_v0_2_variant" in composer_text
    compose_mentions_core = "core_variant_result" in composer_text
    compose_mentions_sidecar = "sidecar_result" in composer_text
    compose_mentions_daily = ("daily_equity_records" in composer_text) or ("daily_records" in composer_text) or ("equity_curve" in composer_text)

    if has_compose_call_in_generator:
        findings.append("Generator references compose_e1r_v0_2_variant.")
    else:
        risks.append("Generator does not directly reference compose_e1r_v0_2_variant; dry-run candidate may be wrapper-only or summary replay.")

    if has_compose_def:
        findings.append("Composer defines compose_e1r_v0_2_variant.")
    else:
        risks.append("Composer definition compose_e1r_v0_2_variant not found by text scan.")

    if has_core_var_in_generator or compose_mentions_core:
        findings.append("core_variant_result is referenced in generator/composer source.")
    else:
        risks.append("core_variant_result not visible in generator/composer source.")

    if has_sidecar_var_in_generator or compose_mentions_sidecar:
        findings.append("sidecar_result is referenced in generator/composer source.")
    else:
        risks.append("sidecar_result not visible in generator/composer source.")

    if has_daily_in_generator or compose_mentions_daily:
        findings.append("daily/equity record names are referenced in generator/composer source.")
    else:
        risks.append("No obvious daily-equity return field in generator/composer text.")

    # Detect whether generator likely writes diagnostic rows.
    if "diagnostic_only" in generator_text:
        findings.append("Generator source references diagnostic_only; persisted equity_curve may be diagnostic, not portfolio-level.")
    if "e1r_v0_2_backtest_equity_curve.json" in generator_text and "e1r_v0_2_backtest_summary.json" in generator_text:
        findings.append("Generator writes both summary and equity_curve export names.")
    if "e1r_v0_2_portfolio_backtest_equity_curve.json" not in generator_text:
        risks.append("Generator does not visibly write portfolio-level E1R canonical filename.")

    next_actions.append("Create a no-write introspection wrapper around compose_e1r_v0_2_variant that captures its actual return object keys and list lengths.")
    next_actions.append("If composer returns only metrics plus diagnostic rows, inspect upstream run_stateful_simulation / run_strategy_variant_comparison return object.")
    next_actions.append("Do not promote exports/e1r_v0_2_backtest_equity_curve.json because 4B-0F-v2 rejected it as symbol/diagnostic rows.")

    return {
        "findings": findings,
        "risks": risks,
        "recommended_next_actions": next_actions,
        "source_flags": {
            "generator_has_compose_call": has_compose_call_in_generator,
            "generator_has_core_variant_result": has_core_var_in_generator,
            "generator_has_sidecar_result": has_sidecar_var_in_generator,
            "generator_has_daily_or_equity_records": has_daily_in_generator,
            "composer_has_compose_def": has_compose_def,
            "composer_mentions_core_variant_result": compose_mentions_core,
            "composer_mentions_sidecar_result": compose_mentions_sidecar,
            "composer_mentions_daily_or_equity_records": compose_mentions_daily,
        },
    }

def run_build_equity_smoke(composer: Any) -> Dict[str, Any]:
    fn = getattr(composer, "build_equity_records_from_returns", None)
    if fn is None:
        return {"ok": False, "error": "build_equity_records_from_returns not found"}

    attempts = []

    candidate_sets = [
        {
            "name": "daily_return_pct",
            "records": [
                {"date": "2021-06-11", "daily_return_pct": 0.0},
                {"date": "2021-06-14", "daily_return_pct": 1.0},
                {"date": "2021-06-15", "daily_return_pct": -0.5},
            ],
        },
        {
            "name": "daily_return_decimal",
            "records": [
                {"date": "2021-06-11", "daily_return": 0.0},
                {"date": "2021-06-14", "daily_return": 0.01},
                {"date": "2021-06-15", "daily_return": -0.005},
            ],
        },
        {
            "name": "return_pct",
            "records": [
                {"date": "2021-06-11", "return_pct": 0.0},
                {"date": "2021-06-14", "return_pct": 1.0},
                {"date": "2021-06-15", "return_pct": -0.5},
            ],
        },
        {
            "name": "interval_return",
            "records": [
                {"start_date": "2021-06-11", "end_date": "2021-06-14", "interval_return": 0.01},
                {"start_date": "2021-06-14", "end_date": "2021-06-15", "interval_return": -0.005},
            ],
        },
        {
            "name": "strategy_return",
            "records": [
                {"date": "2021-06-11", "strategy_return": 0.0},
                {"date": "2021-06-14", "strategy_return": 0.01},
                {"date": "2021-06-15", "strategy_return": -0.005},
            ],
        },
    ]

    for candidate in candidate_sets:
        try:
            res = fn(candidate["records"], 100000.0)
            attempts.append({
                "name": candidate["name"],
                "ok": True,
                "type": type(res).__name__,
                "length": safe_len(res),
                "sample": res[:5] if isinstance(res, list) else str(res)[:500],
            })
        except Exception as exc:
            attempts.append({
                "name": candidate["name"],
                "ok": False,
                "error": type(exc).__name__ + ": " + str(exc),
            })

    return {
        "ok": any(a.get("ok") for a in attempts),
        "attempts": attempts,
    }

def run_leader_engine_validation(
    symbols: list[str],
    prices_map: dict[str, list[float]],
    spx_prices: list[float],
    forward_days: list[int] = [5, 10, 20, 30],
    step: int = 5,           # 每隔 step 天计算一次（节省时间）
    min_history: int = 120,  # 最少需要多少天历史
) -> dict:
    """
    Layer A: Leader Score Bucket Analysis

    对每个时间点 t，计算所有股票的 Leader Score，
    分5个桶，测量前向收益。
    """
    logger.info("[Backtest Layer A] Leader Engine Validation...")

    buckets = {"A": (90, 100), "B": (80, 90), "C": (70, 80),
               "D": (60, 70), "E": (0, 60)}

    # 结果结构：{bucket: {days: [returns]}}
    results = {b: {d: [] for d in forward_days} for b in buckets}

    # 获取最短价格序列长度
    # 用 SPX 长度作为时间轴，避免被个股短数据截断
    n_days = len(spx_prices)

    processed = 0
    for t in range(min_history, n_days - max(forward_days), step):
        # 计算该时间点所有股票的 Leader Score
        day_scores = {}
        for sym in symbols:
            if sym not in prices_map:
                continue
            info = _rebuild_leader_score(
                prices_map[sym], spx_prices,
                prices_map,  # 全量横截面（正式回测）
                t
            )
            if info:
                day_scores[sym] = info

        if len(day_scores) < 20:
            continue

        # 分桶并记录前向收益
        for sym, info in day_scores.items():
            ls = info["leader_score"]
            p_series = prices_map[sym]

            for bucket, (lo, hi) in buckets.items():
                if lo <= ls < hi:
                    for days in forward_days:
                        ret = forward_return(p_series, t, days)
                        if ret is not None:
                            results[bucket][days].append(ret * 100)
                    break

        processed += 1
        if processed % 20 == 0:
            logger.info(f"  Layer A: {t}/{n_days} 天已处理...")

    # 汇总统计
    summary = {}
    for bucket in buckets:
        summary[bucket] = {}
        for days in forward_days:
            rets = results[bucket][days]
            if not rets:
                summary[bucket][f"fwd{days}d"] = {"n": 0}
                continue
            summary[bucket][f"fwd{days}d"] = {
                "n":        len(rets),
                "avg_ret":  round(sum(rets) / len(rets), 3),
                "med_ret":  round(sorted(rets)[len(rets)//2], 3),
                "win_rate": round(sum(1 for r in rets if r > 0) / len(rets) * 100, 1),
                "vol":      round(math.sqrt(sum((r - sum(rets)/len(rets))**2 for r in rets)/len(rets)), 3),
            }

    # 单调性检验
    # 主要标准：A 桶是否是最强桶（最重要）

def run_promotion_engine_validation(
    symbols: list[str],
    prices_map: dict[str, list[float]],
    spx_prices: list[float],
    promotion_thresholds: list[int] = [80, 85, 90],
    track_days: list[int] = [5, 10, 20, 30],
    step: int = 5,
    min_history: int = 120,
) -> dict:
    """
    Layer B: Promotion Engine Validation

    验证 Promotion Score 能否预测未来晋升 Top30。
    注意：需要历史排名数据，首次运行用 Leader Score 近似。
    """
    logger.info("[Backtest Layer B] Promotion Engine Validation...")

    threshold_results = {t: {"promoted": 0, "total": 0} for t in promotion_thresholds}
    all_ret60 = []

    # 用 SPX 长度作为时间轴，避免被个股短数据截断
    n_days = len(spx_prices)
    processed = 0

    for t in range(min_history, n_days - max(track_days), step):
        # 计算全市场横截面
        day_scores = {}
        all_ret60 = []
        for sym in symbols:
            if sym not in prices_map:
                continue
            p = prices_map[sym][:t+1]
            if len(p) < 60:
                continue
            r = period_return(p, 60)
            if r is not None:
                all_ret60.append(r)

        for sym in symbols:
            if sym not in prices_map:
                continue
            p = prices_map[sym][:t+1]
            if len(p) < 60:
                continue
            ret60 = period_return(p, 60) or 0.0
            rs = rs_percentile(ret60, all_ret60)
            mom = calc_momentum(p)["momentum_score"]
            th = calc_trend_health(p)["trend_health"]
            ls = calc_leader_score(rs, mom, th)
            # 用 Leader Score 近似 Promotion Score（历史 RankVelocity 不可用）
            promo_approx = ls
            day_scores[sym] = {"leader_score": ls, "promotion_score": promo_approx}

        if not day_scores:
            continue

        # 当前 Top30
        top30_now = set(sorted(day_scores, key=lambda s: day_scores[s]["leader_score"], reverse=True)[:30])

        # 检查各阈值
        for thresh in promotion_thresholds:
            candidates = [s for s, v in day_scores.items()
                         if v["promotion_score"] >= thresh and s not in top30_now]
            for sym in candidates:
                threshold_results[thresh]["total"] += 1
                # 未来某天进入 Top30？
                for days in track_days:
                    future_t = t + days
                    if future_t >= n_days:
                        continue
                    # 重算未来 Top30
                    future_scores = {}
                    for s in symbols:
                        if s not in prices_map:
                            continue
                        fp = prices_map[s][:future_t+1]
                        if len(fp) < 60:
                            continue
                        fret60 = period_return(fp, 60) or 0.0
                        frs = rs_percentile(fret60, all_ret60)

