def extract_existing_oos_core_equity() -> dict[str, Any]:
    """
    Best-effort bridge to existing legacy OOS equity if present.

    This function does not assume a fixed old schema.
    It tries to find the latest equity value from:
      - exports/oos_summary.json
      - exports/oos_equity_curve.json

    If nothing usable exists, it initializes at 100000.
    """
    summary = read_json(ROOT / "exports/oos_summary.json", {}) or {}
    curve = read_json(ROOT / "exports/oos_equity_curve.json", {}) or {}

    equity = safe_float(
        pick(summary, ["equity", "current_equity", "portfolio_value", "final_equity", "total_equity"]),
        None,
    )

    date = pick(summary, ["date", "status_date", "as_of", "data_date"], None)

    records = None
    if isinstance(curve, list):
        records = curve
    elif isinstance(curve, dict):
        records = (
            curve.get("records")
            or curve.get("equity_curve")
            or curve.get("series")
            or curve.get("data")
        )

    if isinstance(records, list) and records:
        rows = [r for r in records if isinstance(r, dict)]
        if rows:
            rows = sorted(rows, key=lambda r: str(pick(r, ["date", "status_date", "as_of"], "")))
            last = rows[-1]
            equity = safe_float(
                pick(last, ["equity", "total_equity", "portfolio_value", "value"]),
                equity,
            )
            date = pick(last, ["date", "status_date", "as_of"], date)

    if equity is None:
        equity = 100000.0

    return {
        "date": date,
        "equity": equity,
        "source": "legacy_oos_if_available_else_initial_capital",
    }

def extract_latest_regime(regime_json: Any) -> dict[str, Any]:
    daily = regime_json.get("daily_regime") if isinstance(regime_json, dict) else regime_json

    if isinstance(daily, list):
        rows = [r for r in daily if isinstance(r, dict)]
        if not rows:
            raise RuntimeError("daily_regime list is empty")
        rows = sorted(rows, key=lambda r: str(r.get("date", "")))
        return rows[-1]

    if isinstance(daily, dict):
        keys = sorted(daily.keys())
        if not keys:
            raise RuntimeError("daily_regime dict is empty")
        k = keys[-1]
        row = daily[k]
        if not isinstance(row, dict):
            row = {"value": row}
        row = dict(row)
        row.setdefault("date", k)
        return row

    raise RuntimeError("Unsupported spx_regime_daily.json structure")

def rank_entrypoint_candidates(scans: dict[str, Any]) -> list[dict[str, Any]]:
    candidates = []

    for path, scan in scans.items():
        for f in scan.get("function_defs", []):
            name = f["name"]
            lower = name.lower()
            score = f.get("score", 0)

            if "stateful" in lower:
                score += 80
            if "simulation" in lower:
                score += 60
            if "portfolio" in lower:
                score += 50
            if "backtest" in lower:
                score += 40
            if "variant" in lower:
                score += 30
            if name.startswith("run_"):
                score += 20

            body = f.get("body_head", "")
            if "daily_records" in body:
                score += 30
            if "total_equity" in body or "portfolio_value" in body:
                score += 30
            if "cash" in body:
                score += 20
            if "positions_value" in body or "market_value" in body:
                score += 20
            if "spx_regime" in body or "market_gate_state" in body:
                score += 20

            candidates.append({
                "source": path,
                "name": name,
                "line": f.get("line"),
                "end_line": f.get("end_line"),
                "args": f.get("args"),
                "score": score,
                "body_head": body,
            })

    return sorted(candidates, key=lambda x: (-x["score"], x["source"], x["line"]))[:40]

def try_import_backtest() -> dict[str, Any]:
    sys.path.insert(0, str(ROOT))
    sys.path.insert(0, str(ROOT / "src"))

    out = {
        "attempted": True,
        "ok": False,
        "error": None,
        "traceback_tail": None,
        "objects": {},
    }

    try:
        spec = importlib.util.spec_from_file_location("backtest_4c2a", BACKTEST)
        if spec is None or spec.loader is None:
            raise RuntimeError("cannot create import spec")
        mod = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = mod
        spec.loader.exec_module(mod)

        out["ok"] = True

        for name in dir(mod):
            if name.startswith("_"):
                continue
            lower = name.lower()
            if any(k in lower for k in ["backtest", "simulation", "portfolio", "variant", "stateful", "run"]):
                obj = getattr(mod, name)
                item = {"type": type(obj).__name__}
                if callable(obj):
                    try:
                        item["signature"] = str(inspect.signature(obj))
                    except Exception as exc:
                        item["signature_error"] = type(exc).__name__ + ": " + str(exc)
                out["objects"][name] = item

    except Exception as exc:
        out["error"] = type(exc).__name__ + ": " + str(exc)
        out["traceback_tail"] = traceback.format_exc()[-12000:]

    return out

