                {"date": "2021-06-14", "strategy_return": 0.01},
                {"date": "2021-06-15", "strategy_return": -0.005},
            ],
        },
    ]

    for candidate in candidate_sets:
        try:
            res = fn(candidate["records"], 100000.0)
