def walk_for_nodes(node: Any, path: str = "$", depth: int = 0, max_depth: int = 8) -> list[dict[str, Any]]:
    if depth > max_depth:
        return []

    results = []

    if isinstance(node, dict):
        keys = set(node.keys())

        wanted = {
            "metrics",
            "core_variant_result",
            "sidecar_result",
            "daily_equity_records",
            "daily_records",
            "equity_curve",
            "variant_results",
            "records",
            "rows",
            "trades",
            "orders",
        }

        metric_hit = any(k in node for k in TARGETS)
        key_hit = bool(keys.intersection(wanted))

        if metric_hit or key_hit:
            diffs = {}
            matched = {}
            for k, target in TARGETS.items():
                if k in node:
                    val = as_float(node.get(k))
                    if val is not None:
                        matched[k] = val
                        diffs[k] = abs(val - target)

            results.append({
                "path": path,
                "matched_keys": sorted(keys.intersection(wanted)),
                "matched_metrics": matched,
                "target_diffs_abs": diffs,
                "summary": summarize_json_node(node),
            })

        for k, v in node.items():
            if isinstance(v, (dict, list)):
                results.extend(walk_for_nodes(v, f"{path}.{k}", depth + 1, max_depth))

    elif isinstance(node, list):
        for i, v in enumerate(node[:100]):
            if isinstance(v, (dict, list)):
                results.extend(walk_for_nodes(v, f"{path}[{i}]", depth + 1, max_depth))

    return results

def inspect_generated_outputs() -> dict[str, Any]:
    out = {}

    for p in MUTABLE_OUTPUTS:
        item = {
            "path": rel(p),
            "exists_after_run": p.exists(),
            "size_after_run": p.stat().st_size if p.exists() else 0,
            "hash_after_run": sha256(p),
        }

        if p.exists() and p.suffix == ".json" and p.stat().st_size <= 15_000_000:
            try:
                obj = read_json(p)
                nodes = walk_for_nodes(obj)
                exact_metric_nodes = []
                daily_like_nodes = []
                core_nodes = []
                sidecar_nodes = []

                for n in nodes:
                    diffs = n.get("target_diffs_abs") or {}
                    if diffs and all(d <= 0.001 for d in diffs.values()):
                        exact_metric_nodes.append(n)

                    matched_keys = set(n.get("matched_keys") or [])
                    if matched_keys.intersection({"daily_equity_records", "daily_records", "equity_curve", "rows", "records"}):
                        daily_like_nodes.append(n)
                    if "core_variant_result" in matched_keys:
                        core_nodes.append(n)
                    if "sidecar_result" in matched_keys:
                        sidecar_nodes.append(n)

                item["top_summary"] = summarize_json_node(obj)
                item["node_count"] = len(nodes)
                item["exact_metric_node_count"] = len(exact_metric_nodes)
                item["daily_like_node_count"] = len(daily_like_nodes)
                item["core_variant_node_count"] = len(core_nodes)
                item["sidecar_node_count"] = len(sidecar_nodes)
                item["nodes_sample"] = nodes[:30]
                item["exact_metric_nodes"] = exact_metric_nodes[:10]
                item["daily_like_nodes"] = daily_like_nodes[:10]
                item["core_variant_nodes"] = core_nodes[:10]
                item["sidecar_nodes"] = sidecar_nodes[:10]
            except Exception as exc:
                item["inspect_error"] = type(exc).__name__ + ": " + str(exc)

        out[rel(p)] = item

    return out

def validate_portfolio_candidate(stats: dict[str, Any]) -> dict[str, Any]:
    reasons = []

    checks = {
        "row_count_ge_1000": (stats.get("parseable_equity_rows") or 0) >= 1000,
        "one_row_per_date": stats.get("one_row_per_date") is True,
        "not_symbol_level": (stats.get("symbol_row_count") or 0) == 0,
        "not_diagnostic_only": (stats.get("diagnostic_only_row_count") or 0) == 0,
        "max_rows_per_date_eq_1": stats.get("max_rows_per_date") == 1,
        "total_return_close_to_frozen_1pct": (
            stats.get("total_return_abs_diff_vs_frozen") is not None
            and stats["total_return_abs_diff_vs_frozen"] <= 1.0
        ),
        "maxdd_close_to_frozen_1_5pct": (
            stats.get("maxdd_abs_diff_vs_frozen") is not None
            and stats["maxdd_abs_diff_vs_frozen"] <= 1.5
        ),
    }

    for k, ok in checks.items():
        if not ok:
            reasons.append(k)

    return {
        "checks": checks,
        "accepted_as_portfolio_daily_equity": all(checks.values()),
        "rejection_reasons": reasons,
    }

def detect_equity(row: dict[str, Any]):
    for k in ["portfolio_value", "total_equity", "equity", "value", "strategy_equity", "strategy_indexed"]:
        v = as_float(row.get(k))
        if v is not None:
            return v, k
    return None, None

def find_daily_like_lists(obj: Any, source_file: str, path: str = "$", depth: int = 0) -> list[dict[str, Any]]:
    if depth > 10:
        return []

    out = []

    if isinstance(obj, dict):
        for key in ["rows", "records", "daily_equity_records", "daily_records", "equity_curve"]:
            v = obj.get(key)
            if isinstance(v, list) and v and isinstance(v[0], dict):
                stats = summarize_rows(v)
                validation = validate_portfolio_candidate(stats)
                out.append({
                    "source_file": source_file,
                    "json_path": f"{path}.{key}",
                    "list_key": key,
                    "stats": stats,
                    "validation": validation,
                })

        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                out.extend(find_daily_like_lists(v, source_file, f"{path}.{k}", depth + 1))

    elif isinstance(obj, list):
        if obj and isinstance(obj[0], dict):
            stats = summarize_rows(obj)
            if stats["parseable_equity_rows"] > 0:
                validation = validate_portfolio_candidate(stats)
                out.append({
                    "source_file": source_file,
                    "json_path": path,
                    "list_key": None,
                    "stats": stats,
                    "validation": validation,
                })

        for i, v in enumerate(obj[:100]):
            if isinstance(v, (dict, list)):
                out.extend(find_daily_like_lists(v, source_file, f"{path}[{i}]", depth + 1))

    return out

def grep_context(p: Path) -> dict[str, Any] | None:
    text = p.read_text(errors="replace")
    if not any(t in text for t in TARGET_TERMS):
        return None

    lines = text.splitlines()
    hits = []
    score = 0

    for i, line in enumerate(lines, start=1):
        matched = [t for t in TARGET_TERMS if t in line]
        if not matched:
            continue

        score += len(matched)
        if "compose_e1r_v0_2_variant" in matched:
            score += 100
        if "core_variant_result" in matched:
            score += 40
        if "sidecar_result" in matched:
            score += 40
        if "run_strategy_variant_comparison" in matched:
            score += 20
        if "run_stateful_simulation" in matched:
            score += 20
        if "E1R_REGIME_AWARE_V0_2" in matched:
            score += 20

        lo = max(1, i - 5)
        hi = min(len(lines), i + 5)
        hits.append({
            "line": i,
            "matched": matched,
            "context": [
                {"line": j, "text": lines[j - 1][:1000]}
                for j in range(lo, hi + 1)
            ],
        })

    return {
        "path": rel(p),
        "score": score,
        "hit_count": len(hits),
        "hits": hits[:100],
    }

def ast_call_scan(p: Path) -> dict[str, Any]:
    text = p.read_text(errors="replace")
    try:
        tree = ast.parse(text)
    except Exception as exc:
        return {"path": rel(p), "parse_error": type(exc).__name__ + ": " + str(exc), "calls": []}

    calls = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            name = None
            if isinstance(node.func, ast.Name):
                name = node.func.id
            elif isinstance(node.func, ast.Attribute):
                name = node.func.attr

            if name and name in [
                "compose_e1r_v0_2_variant",
                "run_strategy_variant_comparison",
                "run_stateful_simulation",
                "build_equity_records_from_returns",
                "extract_core_interval_returns",
            ]:
                calls.append({
                    "line": getattr(node, "lineno", None),
                    "call": name,
                })

    return {"path": rel(p), "calls": calls}

