def get_run_status(run_date: Optional[date] = None) -> dict:
    """
    Return run status for a given date.
    status values:
      NO_OP_MARKET_CLOSED  — weekend or holiday
      OOS_ACTIVE           — valid trading day, proceed
    """
    if run_date is None:
        run_date = date.today()

    if not is_trading_day(run_date):
        reason = "weekend" if run_date.weekday() >= 5 else "holiday"
        return {
            "status":          "NO_OP_MARKET_CLOSED",
            "reason":          reason,
            "run_date":        run_date.isoformat(),
            "expected_market_date": prev_trading_day(run_date).isoformat(),
        }

    return {
        "status":               "OOS_ACTIVE",
        "run_date":             run_date.isoformat(),
        "expected_market_date": run_date.isoformat(),
    }

def __init__(self):
        self.cash: float = INITIAL_CAPITAL
        self.holdings: dict = {}
        # holdings[sym] = {units, cost_basis, entry_date, entry_price,
        #                   signal_provenance, execution_provenance}
        self.pending_orders: list = []
        self.equity_history: list = []
        self.closed_trades: list = []

def total_equity(self, prices: dict) -> float:
        hv = sum(
            h["units"] * prices.get(sym, h["entry_price"])
            for sym, h in self.holdings.items()
        )
        return self.cash + hv
